INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-daya-tahan', 'tksi-daya-tahan', 1, 'tksi', 'TKSI — Daya Tahan (Lari 1000 m)', '{"id":"tksi-daya-tahan","slug":"tksi-daya-tahan","version":1,"group":"tksi","name":"TKSI — Daya Tahan (Lari 1000 m)","description":"Mengukur daya tahan aerobik melalui lari jarak menengah 1000 meter yang dicatat dalam satuan detik.","purpose":"Menilai kemampuan daya tahan kardiovaskular peserta didik sebagai komponen kebugaran jasmani.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Peserta didik berlari menempuh jarak 1000 meter pada lintasan yang telah diukur.","Waktu dicatat mulai dari aba-aba start sampai peserta melewati garis finis."],"indicators":[{"id":"lari-1000m","name":"Waktu Lari 1000 m","description":"Waktu tempuh lari 1000 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":300,"score":100},{"raw":375,"score":85},{"raw":450,"score":70},{"raw":600,"score":50},{"raw":750,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":375,"score":100},{"raw":450,"score":85},{"raw":525,"score":70},{"raw":675,"score":50},{"raw":825,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":272.73,"score":100},{"raw":340.91,"score":85},{"raw":409.09,"score":70},{"raw":545.45,"score":50},{"raw":681.82,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":340.91,"score":100},{"raw":409.09,"score":85},{"raw":477.27,"score":70},{"raw":613.64,"score":50},{"raw":750,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":255.32,"score":100},{"raw":319.15,"score":85},{"raw":382.98,"score":70},{"raw":510.64,"score":50},{"raw":638.3,"score":25}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":319.15,"score":100},{"raw":382.98,"score":85},{"raw":446.81,"score":70},{"raw":574.47,"score":50},{"raw":702.13,"score":25}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":240,"score":100},{"raw":300,"score":85},{"raw":360,"score":70},{"raw":480,"score":50},{"raw":600,"score":25}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":300,"score":100},{"raw":360,"score":85},{"raw":420,"score":70},{"raw":540,"score":50},{"raw":660,"score":25}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Tes Kebugaran Siswa Indonesia (TKSI)","author":"Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi","year":2021,"publisher":"Kemendikbudristek","url":"https://tksi.kemdikbud.go.id","note":"Instrumen dan norma disesuaikan untuk kelompok usia sekolah di Indonesia."},{"title":"Buku Pedoman Tes Kebugaran Jasmani","author":"Direktorat Jenderal Pendidikan Jasmani","year":2020,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Komponen kebugaran jasmani dan tabel norma hasil adaptasi."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-kekuatan', 'tksi-kekuatan', 1, 'tksi', 'TKSI — Kekuatan (Sit-up 60 Detik)', '{"id":"tksi-kekuatan","slug":"tksi-kekuatan","version":1,"group":"tksi","name":"TKSI — Kekuatan (Sit-up 60 Detik)","description":"Mengukur kekuatan dan daya tahan otot perut melalui sit-up selama 60 detik.","purpose":"Menilai kekuatan dan daya tahan otot inti (core) peserta didik.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Peserta berbaring dengan lutut ditekuk, kedua tangan di dada atau di belakang kepala.","Peserta melakukan sit-up sebanyak mungkin selama 60 detik dengan teknik yang benar.","Hitung hanya gerakan yang mencapai posisi duduk tegak dan kembali dengan benar."],"indicators":[{"id":"situp-60s","name":"Sit-up 60 Detik","description":"Jumlah sit-up benar dalam 60 detik; semakin banyak semakin baik.","unit":"repetisi","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":28,"score":70},{"raw":36,"score":85},{"raw":44,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":6.4,"score":25},{"raw":12.8,"score":50},{"raw":22.4,"score":70},{"raw":29.6,"score":85},{"raw":36,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":8.8,"score":25},{"raw":17.6,"score":50},{"raw":30.8,"score":70},{"raw":39.6,"score":85},{"raw":48.4,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":7.04,"score":25},{"raw":14.08,"score":50},{"raw":24.64,"score":70},{"raw":32.56,"score":85},{"raw":39.6,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":9.4,"score":25},{"raw":18.8,"score":50},{"raw":32.9,"score":70},{"raw":42.3,"score":85},{"raw":51.7,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":7.52,"score":25},{"raw":15.04,"score":50},{"raw":26.32,"score":70},{"raw":34.78,"score":85},{"raw":42.3,"score":100}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":10,"score":25},{"raw":20,"score":50},{"raw":35,"score":70},{"raw":45,"score":85},{"raw":55,"score":100}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":28,"score":70},{"raw":37,"score":85},{"raw":45,"score":100}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Tes Kebugaran Siswa Indonesia (TKSI)","author":"Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi","year":2021,"publisher":"Kemendikbudristek","url":"https://tksi.kemdikbud.go.id","note":"Instrumen dan norma disesuaikan untuk kelompok usia sekolah di Indonesia."},{"title":"ACSM Guidelines for Exercise Testing and Prescription (10th ed.)","author":"American College of Sports Medicine","year":2018,"publisher":"Wolters Kluwer","url":"https://www.acsm.org","note":"Landasan komponen kebugaran jasmani terkait kesehatan."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-kecepatan', 'tksi-kecepatan', 1, 'tksi', 'TKSI — Kecepatan (Lari 50 m)', '{"id":"tksi-kecepatan","slug":"tksi-kecepatan","version":1,"group":"tksi","name":"TKSI — Kecepatan (Lari 50 m)","description":"Mengukur kecepatan lari sprint 50 meter yang dicatat dalam satuan detik.","purpose":"Menilai komponen kecepatan gerak peserta didik secara terukur.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Peserta berdiri di belakang garis start dengan posisi start jongkok atau berdiri.","Guru memberi aba-aba dan mencatat waktu hingga peserta melewati garis finis 50 meter.","Setiap peserta diberi dua kesempatan dan dicatat waktu terbaik."],"indicators":[{"id":"lari-50m","name":"Waktu Lari 50 m","description":"Waktu tempuh lari 50 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":8.75,"score":100},{"raw":9.75,"score":85},{"raw":10.75,"score":70},{"raw":12.5,"score":50},{"raw":14.38,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":10,"score":100},{"raw":11,"score":85},{"raw":12,"score":70},{"raw":13.75,"score":50},{"raw":15.63,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":7.95,"score":100},{"raw":8.86,"score":85},{"raw":9.77,"score":70},{"raw":11.36,"score":50},{"raw":13.07,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":9.09,"score":100},{"raw":10,"score":85},{"raw":10.91,"score":70},{"raw":12.5,"score":50},{"raw":14.2,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":7.45,"score":