INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-kelincahan', 'tksi-kelincahan', 1, 'tksi', 'TKSI — Kelincahan (Shuttle Run 4 × 10 m)', '{"id":"tksi-kelincahan","slug":"tksi-kelincahan","version":1,"group":"tksi","name":"TKSI — Kelincahan (Shuttle Run 4 × 10 m)","description":"Mengukur kelincahan melalui lari bolak-balik 4 × 10 meter dengan mencatat waktu total.","purpose":"Menilai kemampuan mengubah arah gerak dengan cepat dan terkontrol.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Siapkan dua garis berjarak 10 meter dan dua balok/kubus sebagai penanda.","Peserta berlari menuju garis lawan, mengambil balok, dan kembali ke garis awal.","Lakukan empat lintasan dan catat waktu total hingga balok terakhir ditempatkan."],"indicators":[{"id":"shuttle-run-4x10","name":"Waktu Shuttle Run 4 × 10 m","description":"Waktu total lari bolak-balik 4 × 10 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":12.5,"score":100},{"raw":13.75,"score":85},{"raw":15,"score":70},{"raw":17.5,"score":50},{"raw":20,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":13.75,"score":100},{"raw":15,"score":85},{"raw":16.25,"score":70},{"raw":18.75,"score":50},{"raw":21.25,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":11.36,"score":100},{"raw":12.5,"score":85},{"raw":13.64,"score":70},{"raw":15.91,"score":50},{"raw":18.18,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":12.5,"score":100},{"raw":13.64,"score":85},{"raw":14.77,"score":70},{"raw":17.05,"score":50},{"r