INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-koordinasi', 'tksi-koordinasi', 1, 'tksi', 'TKSI — Koordinasi (Lempar Tangkap Bola)', '{"id":"tksi-koordinasi","slug":"tksi-koordinasi","version":1,"group":"tksi","name":"TKSI — Koordinasi (Lempar Tangkap Bola)","description":"Mengukur koordinasi mata-tangan melalui jumlah lempar tangkap bola yang berhasil dalam 30 detik.","purpose":"Menilai koordinasi neuromuskular peserta didik dalam tugas lempar tangkap.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Peserta berdiri pada jarak 2–3 meter dari dinding atau pasangan.","Peserta melakukan lempar tangkap bola secara bergantian selama 30 detik.","Hitung jumlah tangkapan bersih yang berhasil dilakukan."],"indicators":[{"id":"lempar-tangkap-30s","name":"Lempar Tangkap 30 Detik","description":"Jumlah tangkapan bersih dalam 30 detik; semakin banyak semakin baik.","unit":"kali","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":4.8,"score":25},{"raw":8,"score":50},{"raw":11.2,"score":70},{"raw":13.6,"score":85},{"raw":16,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":4,"score":25},{"raw":6.4,"score":50},{"raw":9.6,"score":70},{"raw":12,"score":85},{"raw":14.4,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":5.28,"score":25},{"raw":8.8,"score":50},{"raw":12.32,"score":70},{"raw":14.96,"score":85},{"raw":17.6,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":4.4,"score":25},{"raw":7.04,"score":50},{"raw":10.56,"score":70},{"raw":13.2,"score":85},{"raw":15.84,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15