INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-daya-ledak', 'tksi-daya-ledak', 1, 'tksi', 'TKSI — Daya Ledak (Loncat Tegak)', '{"id":"tksi-daya-ledak","slug":"tksi-daya-ledak","version":1,"group":"tksi","name":"TKSI — Daya Ledak (Loncat Tegak)","description":"Mengukur daya ledak otot tungkai melalui selisih raihan berdiri dan raihan lompat.","purpose":"Menilai kemampuan menghasilkan tenaga secara eksplosif pada otot tungkai.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Ukur raihan berdiri peserta didik dengan lengan terangkat.","Peserta melompat tegak dan menyentuh papan ukur pada raihan tertinggi.","Catat selisih raihan lompat dan raihan berdiri dalam sentimeter."],"indicators":[{"id":"loncat-tegak","name":"Tinggi Loncat Tegak","description":"Selisih raihan lompat dan raihan berdiri dalam sentimeter; semakin tinggi semakin baik.","unit":"sentimeter","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":17.6,"score":25},{"raw":25.6,"score":50},{"raw":35.2,"score":70},{"raw":41.6,"score":85},{"raw":48,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":13.6,"score":25},{"raw":20.8,"score":50},{"raw":28.8,"score":70},{"raw":34.4,"score":85},{"raw":40,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":19.36,"score":25},{"raw":28.16,"score":50},{"raw":38.72,"score":70},{"raw":45.76,"score":85},{"raw":52.8,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":14.96,"score":25},{"raw":22.88,"score":50},{"raw":31.68,"score":70},{"raw":37.84,"score":85},{"raw":44,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15