INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('tksi-terpadu', 'tksi-terpadu', 1, 'tksi', 'TKSI — Instrumen Terpadu', '{"id":"tksi-terpadu","slug":"tksi-terpadu","version":1,"group":"tksi","name":"TKSI — Instrumen Terpadu","description":"Menggabungkan lima butir tes TKSI dan penilaian sikap pelaksanaan tes untuk memperoleh nilai kebugaran menyeluruh.","purpose":"Memberikan gambaran kebugaran jasmani menyeluruh dengan mempertimbangkan hasil tes produk dan sikap saat pelaksanaan.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Laksanakan seluruh butir tes TKSI: lari 1000 m, sit-up, lari 50 m, shuttle run, dan loncat tegak.","Amati sikap peserta didik selama pelaksanaan tes.","Masukkan seluruh hasil ke aplikasi untuk memperoleh nilai proses dan produk."],"indicators":[{"id":"sikap-pelaksanaan","name":"Sikap Pelaksanaan Tes","description":"Kedisiplinan, sportivitas, dan usaha maksimal selama mengikuti rangkaian tes.","unit":"skor","kind":"process","weight":0.2,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"lari-1000m","name":"Waktu Lari 1000 m","description