INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('sepak-bola', 'sepak-bola', 1, 'bola_besar', 'Sepak Bola — Teknik Dasar', '{"id":"sepak-bola","slug":"sepak-bola","version":1,"group":"bola_besar","name":"Sepak Bola — Teknik Dasar","description":"Instrumen penilaian proses keterampilan teknik dasar sepak bola: passing, dribbling, shooting, dan sikap.","purpose":"Menilai kualitas proses keterampilan bermain sepak bola secara terstruktur dan berbasis rubrik.","procedure":["Siapkan lapangan dan bola yang sesuai untuk sepak bola.","Lakukan pemanasan dan jelaskan kriteria penilaian kepada peserta didik.","Amati setiap indikator teknik saat peserta melakukan gerak dasar dalam situasi permainan.","Beri skor 0–100 untuk setiap indikator sesuai rubrik, bukan berdasarkan hasil akhir pertandingan.","Uji passing: peserta melakukan passing dari jarak 5 meter sebanyak 5 kali.","Uji dribbling: peserta menggiring bola melewati 5 cone sejauh 20 meter.","Uji shooting: peserta melakukan tembakan ke gawang dari jarak 10 meter sebanyak 3 kali."],"indicators":[{"id":"passing","name":"Passing","description":"Ketepatan, kekuatan, dan sikap tubuh saat mengumpan bola.","unit":"skor","kind":"process","weight":0.3,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"dribbling","name":"Dribbling","description":"Kontrol bola, perubahan arah, dan kecepatan menggiring bola.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"shooting","name":"Shooting","description":"Akurasi, kekuatan, dan teknik menendang ke arah gawang.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"sikap","name":"Sikap dan Sportivitas","description":"Kedisiplinan, kerja sama, dan sportivitas selama asesmen.","unit":"skor","kind":"process","weight":0.2,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Panduan Penilaian oleh Pendidik dan Satuan Pendidikan untuk SMP","author":"Direktorat Jenderal Pendidikan Dasar dan Menengah","year":2017,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Rubrik proses dan kriteria ketuntasan ranah psikomotor."},{"title":"World Athletics Kids'' Athletics — Teaching Manual","author":"World Athletics","year":2019,"publisher":"World Athletics","url":"https://worldathletics.org","note":"Prinsip teknik dasar dan penilaian nomor atletik anak."}],"assessesProcess":true,"assessesProduct":false,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('bola-basket', 'bola-basket', 1, 'bola_besar', 'Bola Basket — Teknik Dasar', '{"id":"bola-basket","slug":"bola-basket","version":1,"group":"bola_besar","name":"Bola Basket — Teknik Dasar","description":"Instrumen penilaian proses keterampilan teknik dasar bola basket: dribbling, passing, shooting, dan sikap.","purpose":"Menilai kualitas proses keterampilan bermain bola basket melalui rubrik teknik dasar.","procedure":["Siapkan lapangan dan bola yang sesuai untuk bola basket.","Lakukan pemanasan dan jelaskan kriteria penilaian kepada peserta didik.","Amati setiap indikator teknik saat peserta melakukan gerak dasar dalam situasi permainan.","Beri skor 0–100 untuk setiap indikator sesuai rubrik, bukan berdasarkan hasil akhir pertandingan.","Uji dribbling: peserta melakukan dribble zig-zag melewati 5 cone.","Uji passing: peserta melakukan chest pass dan bounce pass dari jarak 4 meter.","Uji shooting: peserta melakukan 5 tembakan dari area free throw."],"indicators":[{"id":"dribbling","name":"Dribbling","description":"Kontrol bola, posisi tubuh rendah, dan pandangan ke lapangan.","unit":"skor","kind":"process","weight":0.3,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"passing","name":"Passing","description":"Ketepatan chest pass dan bounce pass serta koordinasi gerak.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"shooting","name":"Shooting","description":"Rangkaian gerak tembakan, akurasi, dan konsistensi.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"sikap","name":"Sikap dan Sportivitas","description":"Kedisiplinan, kerja sama, dan sportivitas selama asesmen.","unit":"skor","kind":"process","weight":0.2,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Panduan Penilaian oleh Pendidik dan Satuan Pendidikan untuk SMP","author":"Direktorat Jenderal Pendidikan Dasar dan Menengah","year":2017,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Rubrik proses dan kriteria ketuntasan ranah psikomotor."},{"title":"World Athletics Kids'' Athletics — Teaching Manual","author":"World Athletics","year":2019,"publisher":"World Athletics","url":"https://worldathletics.org","note":"Prinsip teknik dasar dan penilaian nomor atletik anak."}],"assessesProcess":true,"assessesProduct":false,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('bola-voli', 'bola-voli', 1, 'bola_besar', 'Bola Voli — Teknik Dasar', '{"id":"bola-voli","slug":"bola-voli","version":1,"group":"bola_besar","name":"Bola Voli — Teknik Dasar","description":"Instrumen penilaian proses keterampilan dasar bola voli: passing atas, passing bawah, servis, dan sikap.","purpose":"Menilai kualitas proses keterampilan bola voli melalui rubrik teknik dasar.","procedure":["Siapkan lapangan dan bola yang sesuai untuk bola voli.","Lakukan pemanasan dan jelaskan kriteria penilaian kepada peserta didik.","Amati setiap indikator teknik saat peserta melakukan gerak dasar dalam situasi permainan.","Beri skor 0–100 untuk setiap indikator sesuai rubrik, bukan berdasarkan hasil akhir pertandingan.","Uji passing atas: peserta melakukan 10 passing atas berurutan ke dinding.","Uji passing bawah: peserta melakukan 10 passing bawah berurutan ke dinding.","Uji servis: peserta melakukan 5 servis bawah atau atas melewati net."],"indicators":[{"id":"passing-atas","name":"Passing Atas","description":"Posisi tangan, perkenaan bola, dan ketinggian umpan.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"passing-bawah","name":"Passing Bawah","description":"Sikap tubuh, perkenaan lengan, dan arah bola.","unit":"skor","kind":"process","weight":0.25,"higherIsBe