 percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Panduan Penilaian oleh Pendidik dan Satuan Pendidikan untuk SMP","author":"Direktorat Jenderal Pendidikan Dasar dan Menengah","year":2017,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Rubrik proses dan kriteria ketuntasan ranah psikomotor."},{"title":"World Athletics Kids'' Athletics — Teaching Manual","author":"World Athletics","year":2019,"publisher":"World Athletics","url":"https://worldathletics.org","note":"Prinsip teknik dasar dan penilaian nomor atletik anak."}],"assessesProcess":true,"assessesProduct":false,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('atletik-lari', 'atletik-lari', 1, 'atletik', 'Atletik — Lari 60 m', '{"id":"atletik-lari","slug":"atletik-lari","version":1,"group":"atletik","name":"Atletik — Lari 60 m","description":"Mengukur kecepatan lari sprint 60 meter.","purpose":"Menilai kemampuan lari cepat peserta didik pada nomor lari jarak pendek.","procedure":["Siapkan lintasan/lapangan, alat ukur, dan alat pencatat waktu.","Lakukan pemanasan menyeluruh sebelum pelaksanaan tes.","Jelaskan teknik dan aturan nomor atletik yang diuji.","Peserta melakukan start jongkok di belakang garis start.","Waktu dicatat dari aba-aba sampai peserta melewati garis finis 60 meter.","Berikan dua kesempatan dan ambil waktu terbaik.","Catat hasil terbaik dari percobaan yang sah."],"indicators":[{"id":"lari-60m","name":"Waktu Lari 60 m","description":"Waktu tempuh lari 60 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":9.38,"score":100},{"raw":10.25,"score":85},{"raw":11.13,"score":70},{"raw":12.5,"score":50},{"raw":15,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":10.63,"score":100},{"raw":11.5,"score":85},{"raw":12.38,"score":70},{"raw":13.75,"score":50},{"raw":16.25,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":8.52,"score":100},{"raw":9.32,"score":85},{"raw":10.11,"score":70},{"raw":11.36,"score":50},{"raw":13.64,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":9.66,"score":100},{"raw":10.45,"score":85},{"raw":11.25,"score":70},{"raw":12.5,"score":50},{"raw":14.77,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":7.98,"score":100},{"raw":8.72,"score":85},{"raw":9.47,"score":70},{"raw":10.64,"score":50},{"raw":12.77,"score":25}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":9.04,"score":100},{"raw":9.79,"score":85},{"raw":10.53,"score":70},{"raw":11.7,"score":50},{"raw":13.83,"score":25}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":7.5,"score":100},{"raw":8.2,"score":85},{"raw":8.9,"score":70},{"raw":10,"score":50},{"raw":12,"score":25}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":8.5,"score":100},{"raw":9.2,"score":85},{"raw":9.9,"score":70},{"raw":11,"score":50},{"raw":13,"score":25}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"World Athletics Kids'' Athletics — Teaching Manual","author":"World Athletics","year":2019,"publisher":"World Athletics","url":"https://worldathletics.org","note":"Prinsip teknik dasar dan penilaian nomor atletik anak."},{"title":"Panduan Penilaian oleh Pendidik dan Satuan Pendidikan untuk SMP","author":"Direktorat Jenderal Pendidikan Dasar dan Menengah","year":2017,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Rubrik proses dan kriteria ketuntasan ranah psikomotor."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('atletik-lompat-jauh', 'atletik-lompat-jauh', 1, 'atletik', 'Atletik — Lompat Jauh', '{"id":"atletik-lompat-jauh","slug":"atletik-lompat-jauh","version":1,"group":"atletik","name":"Atletik — Lompat Jauh","description":"Mengukur jarak lompat jauh awalan berjalan/berlari.","purpose":"Menilai kemampuan lompat jauh peserta didik secara terukur.","procedure":["Siapkan lintasan/lapangan, alat ukur, dan alat pencatat waktu.","Lakukan pemanasan menyeluruh sebelum pelaksanaan tes.","Jelaskan teknik dan aturan nomor atletik yang diuji.","Peserta melakukan awalan, tolakan dengan satu kaki, dan mendarat dengan dua kaki.","Ukur jarak dari titik pendaratan terdekat ke garis tolakan.","Lompatan dinyatakan sah bila tidak menyentuh garis tolakan.","Catat hasil terbaik dari percobaan yang sah."],"indicators":[{"id":"jarak-lompat-jauh","name":"Jarak Lompat Jauh","description":"Jarak lompatan dalam sentimeter; semakin jauh semakin baik.","unit":"sentimeter","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":192,"score":25},{"raw":256,"score":50},{"raw":320,"score":70},{"raw":360,"score":85},{"raw":400,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":160,"score":25},{"raw":216,"score":50},{"raw":272,"score":70},{"raw":304,"score":85},{"raw":336,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":211.2,"score":25},{"raw":281.6,"score":50},{"raw":352,"score":70},{"raw":396,"score":85},{"raw":440,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":176,"score":25},{"raw":237.6,"score":50},{"raw":299.2,"score":70},{"raw":334.4,"score":85},{"raw":369.6,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":225.6,"score":25},{"raw":300.8,"score":50},{"raw":376,"score":70},{"raw":423,"score":85},{"raw":470,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"ra