INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('atletik-lompat-tinggi', 'atletik-lompat-tinggi', 1, 'atletik', 'Atletik — Lompat Tinggi', '{"id":"atletik-lompat-tinggi","slug":"atletik-lompat-tinggi","version":1,"group":"atletik","name":"Atletik — Lompat Tinggi","description":"Mengukur tinggi lompatan dengan gaya gunting atau straddle.","purpose":"Menilai kemampuan lompat tinggi peserta didik secara terukur.","procedure":["Siapkan lintasan/lapangan, alat ukur, dan alat pencatat waktu.","Lakukan pemanasan menyeluruh sebelum pelaksanaan tes.","Jelaskan teknik dan aturan nomor atletik yang diuji.","Peserta melakukan awalan dan tolakan satu kaki melewati mistar.","Tinggi mistar dinaikkan bertahap setelah lompatan sah.","Catat tinggi tertinggi yang berhasil dilewati.","Catat hasil terbaik dari percobaan yang sah."],"indicators":[{"id":"tinggi-lompatan","name":"Tinggi Lompatan","description":"Tinggi mistar tertinggi yang dilewati dalam sentimeter.","unit":"sentimeter","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":72,"score":25},{"raw":88,"score":50},{"raw":104,"score":70},{"raw":116,"score":85},{"raw":128,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":64,"score":25},{"raw":78.4,"score":50},{"raw":92.8,"score":70},{"raw":102.4,"score":85},{"raw":112,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":79.2,"score":25},{"raw":96.8,"score":50},{"raw":114.4,"score":70},{"raw":127.6,"score":85},{"raw":140.8,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":70.4,"score":25},{"raw":86.24,"score":50},{"raw":102.08,"score":70},{"raw":112.64,"score":85},{"raw":123.2,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":84.6,"score":25},{"raw":103.4,"score":50},{"raw":122.2,"score":70},{"raw":136.3,"score":85},{"raw":150.4,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":75.2,"