INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('atletik-tolak-peluru', 'atletik-tolak-peluru', 1, 'atletik', 'Atletik — Tolak Peluru', '{"id":"atletik-tolak-peluru","slug":"atletik-tolak-peluru","version":1,"group":"atletik","name":"Atletik — Tolak Peluru","description":"Mengukur jarak tolakan peluru dengan teknik dasar.","purpose":"Menilai kemampuan tolak peluru peserta didik secara terukur.","procedure":["Siapkan lintasan/lapangan, alat ukur, dan alat pencatat waktu.","Lakukan pemanasan menyeluruh sebelum pelaksanaan tes.","Jelaskan teknik dan aturan nomor atletik yang diuji.","Peserta memegang peluru sesuai aturan dan melakukan tolakan dari lingkaran.","Ukur jarak dari lingkaran ke bekas jatuh peluru.","Tolakan dinyatakan sah bila peserta tidak keluar lingkaran sebelum peluru mendarat.","Catat hasil terbaik dari percobaan yang sah."],"indicators":[{"id":"jarak-tolak-peluru","name":"Jarak Tolak Peluru","description":"Jarak tolakan peluru dalam meter; semakin jauh semakin baik.","unit":"meter","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":4,"score":25},{"raw":5.2,"score":50},{"raw":6.4,"score":70},{"raw":7.2,"score":85},{"raw":8,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":3.2,"score":25},{"raw":4.16,"score":50},{"raw":5.12,"score":70},{"raw":5.76,"score":85},{"raw":6.4,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":4.4,"score":25},{"raw":5.72,"score":50},{"raw":7.04,"score":70},{"raw":7.92,"score":85},{"raw":8.8,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":3.52,"score":25},{"raw":4.58,"score":50},{"raw":5.63,"score":70},{"raw":6.34,"score":85},{"raw":7.04,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":4.7,"score":25},{"raw":6.11,"score":50},{"raw":7.52,"score":70},{"raw":8.46,"score":85},{"raw":9.4,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":