INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-daya-tahan-kardiovaskular', 'kebugaran-daya-tahan-kardiovaskular', 1, 'kebugaran_jasmani', 'Kebugaran — Daya Tahan Kardiovaskular', '{"id":"kebugaran-daya-tahan-kardiovaskular","slug":"kebugaran-daya-tahan-kardiovaskular","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Daya Tahan Kardiovaskular","description":"Mengukur daya tahan kardiovaskular melalui lari 1600 meter.","purpose":"Menilai kapasitas aerobik peserta didik secara tidak langsung.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta berlari menempuh jarak 1600 meter pada lintasan terukur.","Catat waktu tempuh dari start sampai melewati garis finis.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"lari-1600m","name":"Waktu Lari 1600 m","description":"Waktu tempuh lari 1600 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":525,"score":100},{"raw":600,"score":85},{"raw":675,"score":70},{"raw":825,"score":50},{"raw":975,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":600,"score":100},{"raw":675,"score":85},{"raw":750,"score":70},{"raw":900,"score":50},{"raw":1050,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":477.27,"score":100},{"raw":545.45,"score":85},{"raw":613.64,"score":70},{"raw":750,"score":50},{"raw":886.36,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":545.45,"score":100},{"raw":613.64,"score":85},{"raw":681.82,"score":70},{"raw":818.18,"score":50},{"raw":954.55,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":446.81,"score":100},{"raw":510.64,"score":85},{"raw":574.47,"score":70},{"raw":702.13,"score"