INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-kekuatan', 'kebugaran-kekuatan', 1, 'kebugaran_jasmani', 'Kebugaran — Kekuatan (Push-up 60 Detik)', '{"id":"kebugaran-kekuatan","slug":"kebugaran-kekuatan","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Kekuatan (Push-up 60 Detik)","description":"Mengukur kekuatan dan daya tahan otot lengan, dada, dan bahu.","purpose":"Menilai kekuatan otot bagian atas peserta didik.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta melakukan push-up dengan posisi tubuh lurus selama 60 detik.","Hitung hanya push-up dengan rentang gerak yang benar.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"pushup-60s","name":"Push-up 60 Detik","description":"Jumlah push-up benar dalam 60 detik; semakin banyak semakin baik.","unit":"repetisi","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":6.4,"score":25},{"raw":12.8,"score":50},{"raw":20.8,"score":70},{"raw":26.4,"score":85},{"raw":32,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":4,"score":25},{"raw":8,"score":50},{"raw":14.4,"score":70},{"raw":19.2,"score":85},{"raw":24,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":7.04,"score":25},{"raw":14.08,"score":50},{"raw":22.88,"score":70},{"raw":29.04,"score":85},{"raw":35.2,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":4.4,"score":25},{"raw":8.8,"score":50},{"raw":15.84,"score":70},{"raw":21.12,"score":85},{"raw":26.4,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":7.52,"score":25},{"raw":15.04,"score":50},{"raw":24.44,"score":70},{"raw":31.02,"score":85},{"raw":37.6,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":4.7,"score":25},{"