INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-kecepatan', 'kebugaran-kecepatan', 1, 'kebugaran_jasmani', 'Kebugaran — Kecepatan (Sprint 30 m)', '{"id":"kebugaran-kecepatan","slug":"kebugaran-kecepatan","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Kecepatan (Sprint 30 m)","description":"Mengukur kecepatan akselerasi melalui lari sprint 30 meter.","purpose":"Menilai komponen kecepatan peserta didik.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta melakukan sprint 30 meter dari posisi start berdiri.","Catat waktu tempuh dan ambil waktu terbaik dari dua percobaan.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"lari-30m","name":"Waktu Sprint 30 m","description":"Waktu tempuh sprint 30 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":5.25,"score":100},{"raw":5.75,"score":85},{"raw":6.25,"score":70},{"raw":7.25,"score":50},{"raw":8.25,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":5.75,"score":100},{"raw":6.25,"score":85},{"raw":6.75,"score":70},{"raw":7.75,"score":50},{"raw":8.75,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":4.77,"score":100},{"raw":5.23,"score":85},{"raw":5.68,"score":70},{"raw":6.59,"score":50},{"raw":7.5,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":5.23,"score":100},{"raw":5.68,"score":85},{"raw":6.14,"score":70},{"raw":7.05,"score":50},{"raw":7.95,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":4.47,"score":100},{"raw":4.89,"score":85},{"raw":5.32,"score":70},{"raw":6.17,"score":50},{"raw":7.02,"score":25}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":4.89,"score":100},{"raw":