INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-koordinasi', 'kebugaran-koordinasi', 1, 'kebugaran_jasmani', 'Kebugaran — Koordinasi (Lempar Tangkap)', '{"id":"kebugaran-koordinasi","slug":"kebugaran-koordinasi","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Koordinasi (Lempar Tangkap)","description":"Mengukur koordinasi mata-tangan melalui lempar tangkap bola.","purpose":"Menilai koordinasi neuromuskular peserta didik.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta melakukan lempar tangkap bola ke dinding/pasangan selama 30 detik.","Hitung jumlah tangkapan bersih yang berhasil.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"lempar-tangkap-30s","name":"Lempar Tangkap 30 Detik","description":"Jumlah tangkapan bersih dalam 30 detik; semakin banyak semakin baik.","unit":"kali","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":4.8,"score":25},{"raw":8,"score":50},{"raw":11.2,"score":70},{"raw":13.6,"score":85},{"raw":16,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":4,"score":25},{"raw":6.4,"score":50},{"raw":9.6,"score":70},{"raw":12,"score":85},{"raw":14.4,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":5.28,"score":25},{"raw":8.8,"score":50},{"raw":12.32,"score":70},{"raw":14.96,"score":85},{"raw":17.6,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":4.4,"score":25},{"raw":7.04,"score":50},{"raw":10.56,"score":70},{"raw":13.2,"score":85},{"raw":15.84,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":5.64,"score":25},{"raw":9.4,"score":50},{"raw":13.16,"score":70},{"raw":15.98,"score":85},{"raw":18.8,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":4.7,"