INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-daya-ledak', 'kebugaran-daya-ledak', 1, 'kebugaran_jasmani', 'Kebugaran — Daya Ledak (Lompat Jauh Berdiri)', '{"id":"kebugaran-daya-ledak","slug":"kebugaran-daya-ledak","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Daya Ledak (Lompat Jauh Berdiri)","description":"Mengukur daya ledak otot tungkai melalui standing broad jump.","purpose":"Menilai kemampuan menghasilkan tenaga eksplosif otot tungkai.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta berdiri di belakang garis dan melompat sejauh mungkin dengan dua kaki.","Ukur jarak dari garis tolakan ke titik pendaratan terdekat.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"lompat-jauh-berdiri","name":"Jarak Lompat Jauh Berdiri","description":"Jarak lompatan dalam sentimeter; semakin jauh semakin baik.","unit":"sentimeter","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":88,"score":25},{"raw":112,"score":50},{"raw":136,"score":70},{"raw":156,"score":85},{"raw":176,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":76,"score":25},{"raw":96,"score":50},{"raw":116.8,"score":70},{"raw":134.4,"score":85},{"raw":152,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":96.8,"score":25},{"raw":123.2,"score":50},{"raw":149.6,"score":70},{"raw":171.6,"score":85},{"raw":193.6,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":83.6,"score":25},{"raw":105.6,"score":50},{"raw":128.48,"score":70},{"raw":147.84,"score":85},{"raw":167.2,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":103.4,"score":25},{"raw":131.6,"score":50},{"raw":159.8,"score":70},{"raw":183.3,"score":85},{"raw":206.8,"score":100}]