INSERT INTO instruments (id, slug, version, "group", name, payload_json, created_at) VALUES ('kebugaran-keseimbangan', 'kebugaran-keseimbangan', 1, 'kebugaran_jasmani', 'Kebugaran — Keseimbangan (Stork Stand)', '{"id":"kebugaran-keseimbangan","slug":"kebugaran-keseimbangan","version":1,"group":"kebugaran_jasmani","name":"Kebugaran — Keseimbangan (Stork Stand)","description":"Mengukur keseimbangan statis melalui sikap stork stand.","purpose":"Menilai kemampuan mempertahankan keseimbangan tubuh.","procedure":["Siapkan alat ukur dan area tes yang aman.","Lakukan pemanasan 5–10 menit sebelum tes.","Jelaskan teknik dan aturan pelaksanaan tes kepada peserta didik.","Peserta berdiri dengan satu kaki dan kaki lain menempel pada lutut kaki tumpu.","Kedua tangan di pinggang dan mata tertutup selama tes.","Catat waktu bertahan hingga peserta kehilangan keseimbangan.","Catat hasil terbaik dan hentikan tes bila peserta mengalami keluhan fisik."],"indicators":[{"id":"stork-stand","name":"Waktu Stork Stand","description":"Lama bertahan dalam sikap stork stand (detik); semakin lama semakin baik.","unit":"detik","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":6.4,"score":25},{"raw":12,"score":50},{"raw":20,"score":70},{"raw":28,"score":85},{"raw":36,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":6.4,"score":25},{"raw":12,"score":50},{"raw":20,"score":70},{"raw":28,"score":85},{"raw":36,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":7.04,"score":25},{"raw":13.2,"score":50},{"raw":22,"score":70},{"raw":30.8,"score":85},{"raw":39.6,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":7.04,"score":25},{"raw":13.2,"score":50},{"raw":22,"score":70},{"raw":30.8,"score":85},{"raw":39.6,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":7.52,"score":25},{"raw":14.1,"score":50},{"raw":23.5,"score":70},{"raw":32.9,"score":85},{"raw":42.3,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":7.52,"score":25},{"raw":14.1,"score":50},{"raw":23.5,"score":70},{"raw":32.9,"score":85},{"raw":42.3,"score":100}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":8,"score":25},{"raw":15,"score":50},{"raw":25,"score":70},{"raw":35,"score":85},{"raw":45,"score":100}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":8,"score":25},{"raw":15,"score":50},{"raw":25,"score":70},{"raw":35,"score":85},{"raw":45,"score":100}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Buku Pedoman Tes Kebugaran Jasmani","author":"Direktorat Jenderal Pendidikan Jasmani","year":2020,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Komponen kebugaran jasmani dan tabel norma hasil adaptasi."},{"title":"ACSM Guidelines for Exercise Testing and Prescription (10th ed.)","author":"American College of Sports Medicine","year":2018,"publisher":"Wolters Kluwer","url":"https://www.acsm.org","note":"Landasan komponen kebugaran jasmani terkait kesehatan."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '2025-01-01T00:00:00.000Z') ON CONFLICT(slug, version) DO UPDATE SET name = excluded.name, "group" = excluded."group", payload_json = excluded.payload_json;
